test('Cursor hiding follows free image hover and restores for pinning, margins, controls and inactive views',async()=>{
 const h=environment({width:80,height:70,stored:{size:4},followPointer:true,readWholeHistogram:nativeWhole}),hidden=()=>h.viewport.classList.contains('local-histogram-cursor-hidden');try{
  h.controller.sync();await h.finish();assert.equal(hidden(),false);h.move(10,12);await h.finish();assert.equal(hidden(),true);
  h.input('local-histogram-freeze').onclick();assert.equal(hidden(),false,'Pinning restores the cursor immediately');h.move(90,80);await h.finish();assert.equal(h.overlay().hidden,false,'The pinned rectangle remains on screen');assert.equal(hidden(),false,'Margins keep their ordinary cursor even with a visible pinned rectangle');h.move(10,12);await h.finish();assert.equal(hidden(),false,'A pinned rectangle keeps the pointer visible on the image');h.input('local-histogram-freeze').onclick();assert.equal(hidden(),true,'Unpinning under the pointer resumes the hidden free-follow cursor');
  const control=h.document.createElement('button');h.viewport.append(control);const event=new h.window.Event('pointermove',{bubbles:true});Object.defineProperties(event,{clientX:{value:10},clientY:{value:12},buttons:{value:0}});control.dispatchEvent(event);assert.equal(hidden(),false,'Controls do not inherit the hidden histogram pointer');h.move(10,12);assert.equal(hidden(),true);
  h.input('local-histogram-scope').value='whole';h.input('local-histogram-scope').onchange();await h.finish();assert.equal(hidden(),false);h.input('local-histogram-scope').value='local';h.input('local-histogram-scope').onchange();await h.finish();assert.equal(hidden(),true);
  h.setCamera({scale:1,x:200,y:200});h.controller.draw();assert.equal(h.overlay().hidden,true);assert.equal(hidden(),false);h.setCamera({scale:1,x:0,y:0});h.controller.draw();assert.equal(hidden(),true);
  h.controller.sync(false);assert.equal(hidden(),false);h.controller.sync(true);await h.finish();h.move(10,12);assert.equal(hidden(),true);h.setSource(null);h.controller.sync();assert.equal(hidden(),false);h.setSource(h.makeSource('source-B',80,70));h.controller.sync();await h.finish();h.move(10,12);await h.finish();assert.equal(hidden(),true);await h.controller.dispose();assert.equal(hidden(),false);
 }finally{await h.close();}
});
test('Image clicks, the pin button and Enter restore the cursor on lock and hide it again on release',async()=>{
 const h=environment({width:80,height:70,stored:{size:4},followPointer:true,readWholeHistogram:nativeWhole}),hidden=()=>h.viewport.classList.contains('local-histogram-cursor-hidden');try{
  h.controller.sync();await h.finish();h.move(10,12);await h.finish();const reads=h.calls.length,computed=h.controller.snapshot().computed;assert.equal(hidden(),true);
  h.click(10,12);assert.equal(h.controller.snapshot().pinned,true);assert.equal(hidden(),false,'An image click restores the pointer before another calculation');h.move(30,35);await h.finish();assert.equal(hidden(),false);h.move(10,12);h.click(10,12);assert.equal(h.controller.snapshot().pinned,false);assert.equal(hidden(),true,'A second image click resumes free following immediately');
  h.input('local-histogram-freeze').onclick();assert.equal(h.controller.snapshot().pinned,true);assert.equal(hidden(),false);h.input('local-histogram-freeze').onclick();assert.equal(h.controller.snapshot().pinned,false);assert.equal(hidden(),true);
  h.dispatch('keydown',{key:'Enter'});assert.equal(h.controller.snapshot().pinned,true);assert.equal(hidden(),false);h.dispatch('keydown',{key:'Enter'});assert.equal(h.controller.snapshot().pinned,false);assert.equal(hidden(),true);await h.finish();assert.equal(h.calls.length,reads);assert.equal(h.controller.snapshot().computed,computed,'Cursor and locking changes reuse the already calculated region');
 }finally{await h.close();}
});
